UPDATE ui.dashboardquery SET
vcdashboardquery =  E'   {
  "All": 
  { 
      "All" : {
          "All" :  "WITH filtered_rule_triggers AS ( SELECT rt.ilivemessageid, rt.dttrxntime, rt.vcmsgid, rt.vcpayercustomerexternalid, rt.vcpayeraccountexternalid, rt.vcpayeraddr, rt.vcpayeecustomerexternalid, rt.vcpayeeaccountexternalid, rt.vcpayeeaddr, rt.vcclassname, rt.dobservationamount, rt.vcdecisionname, rt.iruleid, rt.vcrulename, rt.rule_score, rt.vcremark FROM t14refined.analytics.rule_triggered rt WHERE rt.rule_score >= :RiskScore AND rt.dttrxntime between :StartDate AND :EndDate AND rt.itenantid = :tenantid ORDER BY rt.dttrxntime DESC LIMIT :Load ), joined_transactions AS ( SELECT l.observations, l.result, rt.* FROM filtered_rule_triggers rt LEFT JOIN t14refined.analytics.trans l ON l.ilivemessageid = rt.ilivemessageid WHERE l.tdate BETWEEN :StartDate AND :EndDate ) SELECT ilivemessageid AS \\"id\\", json_extract_scalar(observations, ''$.reqid'') AS \\"Request ID\\", json_extract_scalar(observations, ''$.ts'') AS \\"Timestamp\\", json_extract_scalar(result, ''$.msg'') AS \\"Remarks\\", json_extract_scalar(observations, ''$.org'') AS \\"Org\\", json_extract_scalar(result, ''$.status'') AS \\"Status\\", json_extract_scalar(observations, ''$.txn.id'') AS \\"Txn ID\\", json_extract_scalar(observations, ''$.txn.ts'') AS \\"Txn Timestamp\\", json_extract_scalar(observations, ''$.txn.note'') AS \\"Note\\", json_extract_scalar(observations, ''$.txn.type'') AS \\"Type\\", json_extract_scalar(observations, ''$.txn.class'') AS \\"Class\\", json_extract_scalar(observations, ''$.payee.addr'') AS \\"Merchant addr\\", json_extract_scalar(observations, ''$.payee.attribs.identity.verified_name'') AS \\"Payee Name\\", json_extract_scalar(observations, ''$.observations.payeeVPA.payment_address'') AS \\"Payee VPA\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.accountName'') AS \\"Account Name\\", json_extract_scalar(observations, ''$.observations.payeeVPA.account.default_mcc'') AS \\"Default MCC\\", json_extract_scalar(observations, ''$.payee.mcc'')